#!/bin/bash
# Driver: every chunk through a queue of NP single-thread slots (xargs -P), then (if all chunks are postprocessed and
# none failed) the aggregation (03_aggregate.py, read at call time, so it can still be edited while the search runs).
# Restart-safe: finished chunks (hmm/chunk_X.done, results/chunks/chunk_X.postprocessed) are skipped.
# Launch:  nohup setsid bash scripts/run_all.sh > logs/run_all.nohup 2>&1 < /dev/null &
# DO NOT EDIT this file or run_chunk.sh while it runs (bash reads running scripts lazily by byte offset).
set -uo pipefail
W=/scratch1/afreiburger/salterns_2026/community_ko
A=/scratch1/afreiburger/emilykin/processed/.snakemake_envs/544db00dd5c254ecfa7c6335967a046f_/bin
NP=${NP:-90}
cd $W
export TMPDIR=$W/tmp
mkdir -p logs/chunks results/chunks hmm
echo "$(date -u +%FT%TZ) run_all start pid $$ NP $NP host $(hostname) load $(cut -d' ' -f1-3 /proc/loadavg)" >> logs/run_all.log
ls chunks/ | sed -n 's/^chunk_\([0-9]*\)\.faa$/\1/p' | xargs -P $NP -I{} bash scripts/run_chunk.sh {}
nch=$(ls chunks/ | grep -c '^chunk_[0-9]*\.faa$')
nd=$(ls results/chunks/ | grep -c '\.postprocessed$')
nf=$(ls hmm/ results/chunks/ | grep -c 'failed$')
echo "$(date -u +%FT%TZ) search finished: chunks $nch postprocessed $nd failed $nf" >> logs/run_all.log
if [ "$nd" -eq "$nch" ] && [ "$nf" -eq 0 ]; then
    touch SEARCH_DONE
    echo "$(date -u +%FT%TZ) aggregate start" >> logs/run_all.log
    nice -n 10 $A/python3 -I scripts/03_aggregate.py $W >> logs/03_aggregate.log 2>&1 && touch ALL_DONE
    echo "$(date -u +%FT%TZ) aggregate end rc=$?" >> logs/run_all.log
fi
echo "$(date -u +%FT%TZ) run_all end" >> logs/run_all.log
